import{d as p,C as s,o as g,c as d,a3 as t,E as e,j as a,a as h}from"./chunks/framework.Q4yG9rk_.js";const m=JSON.parse('{"title":"正易心法·第三十二章","description":"《正易心法》第三十二章——数成于三，重之则六：气之数起于一、偶于二、成于三，重之为六；三为少阳（春）、六为太阳（夏）是进数，三为少阴（秋）、六为太阴（冬）是退数；三画经卦、六画重卦之由。","frontmatter":{"title":"正易心法·第三十二章","description":"《正易心法》第三十二章——数成于三，重之则六：气之数起于一、偶于二、成于三，重之为六；三为少阳（春）、六为太阳（夏）是进数，三为少阴（秋）、六为太阴（冬）是退数；三画经卦、六画重卦之由。","category":"guide","aliases":["正易心法第三十二章","数成于三重之则六","进退之数"],"source":["《正易心法》"],"outline":[2,3]},"headers":[],"relativePath":"yijing/zheng-yi-xin-fa/chapter-32.md","filePath":"yijing/zheng-yi-xin-fa/chapter-32.md","lastUpdated":1790647676000}'),c={name:"yijing/zheng-yi-xin-fa/chapter-32.md"},x=p({...c,setup(u){const i=[{id:"z32-01",label:"一、数成于三",showLabel:!0,sentences:[["数成于三，重之则六。其退亦六，是为乾坤。"]],note:["数在三这里完成，将三重叠则得六；退行的方向也是六——这就是乾坤之数。（**本章回答的是「元问题」**：为什么是六爻？为什么不是四画、五画？**答案：因为气数完备于三，重叠则为六**——**三画经卦、六画重卦，不是人为规定，是自然完备的节点。**）"]},{id:"z32-02",label:"二、起一偶二成三",showLabel:!0,sentences:[["夫气之数，起于一，偶于二，成于三，",{text:"无以加",glossary:"wuyijia"},"矣。重之则为六也。"]],note:["气的数，从一开始，在二处成偶，在三处完成，没有什么可以再加的了；将三重叠，就成为六。（**数的三个阶段**：一＝起点，奇数之始，阳之萌动；二＝成偶，阴阳分化，有了对立；三＝完成，天、地、人三才具备。**为什么三是完成？因为任何结构有了「两端＋中介」就完备了**——天（上）＋地（下）＋人（中），起点＋终点＋过程。）"]},{id:"z32-03",label:"三、乾之进数",showLabel:!0,sentences:[["然三，",{text:"少阳",glossary:"shaoyang"},"也。六，",{text:"太阳",glossary:"taiyang"},"也。三，春也。六，夏也。此乾之数也，是为",{text:"进数",glossary:"jinshu"},"。"]],note:["然而三是少阳，六是太阳；三是春，六是夏。这是乾的数，是进数。（**方向：向前、向上、生长、发散。**「太阳」在此是「阳气之太（极）」，不是今天说的日头；「少阳」是阳气初生。**三爻（经卦）是阳气初成，六爻（重卦）是阳气极盛。**）"]},{id:"z32-04",label:"四、乾坤之退数",showLabel:!0,sentences:[["其退亦六。三，",{text:"少阴",glossary:"shaoyin"},"也。六，",{text:"太阴",glossary:"taiyin"},"也。三，秋也。六，冬也。此乾坤之数也，是为",{text:"退数",glossary:"tuishu"},"。"]],note:["退行方向也是六：三是少阴，六是太阴；三是秋，六是冬。这是乾坤的数，是退数。（**有趣的对称**：三与六各出现两次——「少阳／太阳」一组，「少阴／太阴」一组；「春／夏」一组，「秋／冬」一组。**同一个数字，在进与退两个方向上是同一位置的两种性质：三既是「阳之初」，也是「阴之初」；六既是「阳之极」，也是「阴之极」。**）"]},{id:"z32-05",label:"五、三画与六画",showLabel:!0,sentences:[["三画为经卦，六画为重卦者，凡以此而已。"]],note:["三爻为经卦、六爻为重卦，全都是因为这个道理。（**这是本章的落点**：**不是「圣人规定三爻和六爻」，而是「气数自然完备于三、自然重叠为六」。** 三画六画，是自然之理，非人为设计——与第二十章「本之自然」、第二十八章「不可得而容心」同一立场。）"]}],o=[{id:"wuyijia",term:"无以加",pinyin:"wú yǐ jiā",meaning:"没有什么可以再加的了。三已经是气数的完备状态。"},{id:"shaoyang",term:"少阳",pinyin:"shào yáng",meaning:"阳气的初生阶段（三），对应春天。"},{id:"taiyang",term:"太阳",pinyin:"tài yáng",meaning:"阳气的极盛阶段（六），对应夏天。此处「太阳」指阳气之太，非今日的日头。"},{id:"shaoyin",term:"少阴",pinyin:"shào yīn",meaning:"阴气的初生阶段（三），对应秋天。"},{id:"taiyin",term:"太阴",pinyin:"tài yīn",meaning:"阴气的极盛阶段（六），对应冬天。"},{id:"jinshu",term:"进数",pinyin:"jìn shù",meaning:"向前增长的数。阳气从少到太，从三到六，是进。"},{id:"tuishu",term:"退数",pinyin:"tuì shù",meaning:"向后收缩的数。阴气从少到太，从三到六，是退（阳退）。"}];return(b,n)=>{const r=s("DaoTextReading"),l=s("DaoKeywordCards");return g(),d("div",null,[n[0]||(n[0]=t(`<h1 id="正易心法·第三十二章" tabindex="-1">正易心法·第三十二章 <a class="header-anchor" href="#正易心法·第三十二章" aria-label="Permalink to &quot;正易心法·第三十二章&quot;">​</a></h1><h2 id="是什么" tabindex="-1">是什么 <a class="header-anchor" href="#是什么" aria-label="Permalink to &quot;是什么&quot;">​</a></h2><p>本章的核心命题：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>气之数：起于一 → 偶于二 → 成于三（无以加矣）</span></span>
<span class="line"><span>重之则六</span></span>
<span class="line"><span></span></span>
<span class="line"><span>进数（乾）：三＝少阳＝春；六＝太阳＝夏</span></span>
<span class="line"><span>退数（坤）：三＝少阴＝秋；六＝太阴＝冬</span></span>
<span class="line"><span></span></span>
<span class="line"><span>三画经卦、六画重卦，凡以此而已</span></span></code></pre></div><p><strong>这是对「元问题」的回答</strong>：<strong>为什么是六爻？</strong> 因为<strong>气数完备于三，重叠则为六</strong>。</p><h2 id="为什么重要" tabindex="-1">为什么重要 <a class="header-anchor" href="#为什么重要" aria-label="Permalink to &quot;为什么重要&quot;">​</a></h2><p><strong>数的三个阶段</strong>：</p><table tabindex="0"><thead><tr><th>数</th><th>阶段</th><th>含义</th></tr></thead><tbody><tr><td>一</td><td>起</td><td>奇数之始，阳之萌动（未分化的原初之气）</td></tr><tr><td>二</td><td>偶</td><td>阴阳相对，两仪既立（有了对立）</td></tr><tr><td>三</td><td>成</td><td>天、地、人三才具备（结构完备，无以加矣）</td></tr></tbody></table><p><strong>为什么三是完成？</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>因为任何结构，有了「两端 + 中介」就完备了：</span></span>
<span class="line"><span>  天（上）+ 地（下）+ 人（中）</span></span>
<span class="line"><span>  阳（进）+ 阴（退）+ 和（中）</span></span>
<span class="line"><span>  起点 + 终点 + 过程</span></span>
<span class="line"><span>= 三是最小的完备结构</span></span></code></pre></div><p><strong>进数与退数的完整图</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>进数（乾，阳）：</span></span>
<span class="line"><span>  一 → 二 → 三（少阳／春）→ 六（太阳／夏）</span></span>
<span class="line"><span>  起   偶   成·经卦            重·极盛</span></span>
<span class="line"><span>  方向：向前、向上、生长、发散</span></span>
<span class="line"><span></span></span>
<span class="line"><span>退数（坤，阴）：</span></span>
<span class="line"><span>  一 → 二 → 三（少阴／秋）→ 六（太阴／冬）</span></span>
<span class="line"><span>  起   偶   成·经卦            重·极盛</span></span>
<span class="line"><span>  方向：向后、向下、收藏、聚敛</span></span></code></pre></div><p><strong>进六（夏）＋退六（冬）＝乾坤各有其极，各有其六。</strong></p><p><strong>为什么进数与退数都是六？</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>六不是一个「量」，而是一个「完备状态」</span></span>
<span class="line"><span>  进到六 = 阳气完备（不能再进）</span></span>
<span class="line"><span>  退到六 = 阴气完备（不能再退）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>就像：一年最热是夏（阳极），最冷是冬（阴极）——两者都是「极」，都是完备</span></span></code></pre></div><p><strong>这也解释了为什么六爻卦是完备的</strong>：六爻＝阴阳各自完备的叠加＝宇宙最完整的表达单位。</p><h2 id="怎么读" tabindex="-1">怎么读 <a class="header-anchor" href="#怎么读" aria-label="Permalink to &quot;怎么读&quot;">​</a></h2><ol><li>先把「一、二、三」三个阶段记住：<strong>起、偶、成</strong>；</li><li>再看进数与退数两列：<strong>三与六各出现两次（少阳／太阳、少阴／太阴）</strong>；</li><li>最后读「凡以此而已」——<strong>这就是三画六画的全部理由。</strong></li></ol><h2 id="核心内容要点" tabindex="-1">核心内容要点 <a class="header-anchor" href="#核心内容要点" aria-label="Permalink to &quot;核心内容要点&quot;">​</a></h2><ul><li><strong>数成于三</strong>：一的起点、二的成偶、三的完成。</li><li><strong>无以加</strong>：三是完备的节点。</li><li><strong>重之则六</strong>：三重叠得六。</li><li><strong>进数</strong>：少阳（春三）→ 太阳（夏六）。</li><li><strong>退数</strong>：少阴（秋三）→ 太阴（冬六）。</li><li><strong>三画六画</strong>：经卦三画、重卦六画，皆由气数自然。</li></ul><h2 id="【原典层】原文" tabindex="-1">【原典层】原文 <a class="header-anchor" href="#【原典层】原文" aria-label="Permalink to &quot;【原典层】原文&quot;">​</a></h2>`,21)),e(r,{colophon:"数成于三 · 起一偶二成三 · 进数退数 · 三画六画",tone:"ink",density:"comfortable","default-mode":"slips","mode-switch":!0,"aria-label":"正易心法第三十二章原文",sections:i,glossary:o}),n[1]||(n[1]=a("blockquote",null,[a("p",null,"注：本页依所据底本录入，用字随底本，不作统一。原文「此乾坤之数也」承上文「此乾之数也」而言，读者可并观。")],-1)),n[2]||(n[2]=a("h2",{id:"【原典层】字词释义",tabindex:"-1"},[h("【原典层】字词释义 "),a("a",{class:"header-anchor",href:"#【原典层】字词释义","aria-label":'Permalink to "【原典层】字词释义"'},"​")],-1)),e(l,{items:[{term:"起一偶二成三",pinyin:["qǐ","yī"],meaning:"一＝起点（阳之萌动）；二＝成偶（阴阳分化）；三＝完成（天地人三才，无以加矣）。"},{term:"重之则六",pinyin:["chóng","zhī"],meaning:"将三重叠则得六——三画经卦叠为六画重卦，非人为规定。"},{term:"进数 · 退数",pinyin:["jìn","shù"],meaning:"进数：少阳（春三）→ 太阳（夏六）；退数：少阴（秋三）→ 太阴（冬六）。"},{term:"其退亦六",pinyin:["qí","tuì"],meaning:"退的方向也到六——六不是量，是「完备状态」：阳到六而极，阴到六也极。"},{term:"三画六画",pinyin:["sān","huà"],meaning:"三画为经卦、六画为重卦的理由：气数完备于三，自然重叠为六。"}]}),n[3]||(n[3]=t(`<h2 id="【解读层】三问解读" tabindex="-1">【解读层】三问解读 <a class="header-anchor" href="#【解读层】三问解读" aria-label="Permalink to &quot;【解读层】三问解读&quot;">​</a></h2><h3 id="象-这一章在说什么" tabindex="-1">象：这一章在说什么 <a class="header-anchor" href="#象-这一章在说什么" aria-label="Permalink to &quot;象：这一章在说什么&quot;">​</a></h3><p>本章的核心命题：<strong>气数起于一、偶于二、成于三，重之为六；三为少阳（春）、六为太阳（夏）是进数，三为少阴（秋）、六为太阴（冬）是退数</strong>——<strong>这就是三画经卦、六画重卦的理由。</strong></p><h3 id="理-为什么这样说" tabindex="-1">理：为什么这样说 <a class="header-anchor" href="#理-为什么这样说" aria-label="Permalink to &quot;理：为什么这样说&quot;">​</a></h3><p><strong>进六与退六，为什么都是六？</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>六不是一个「量」，而是一个「完备状态」</span></span>
<span class="line"><span>  进到六 = 阳气完备（不能再进）</span></span>
<span class="line"><span>  退到六 = 阴气完备（不能再退）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>就像一年最热是夏（阳极）、最冷是冬（阴极）——两者都是「极」</span></span>
<span class="line"><span>= 六是完备的象征，不是具体的量</span></span></code></pre></div><p><strong>这也解释了为什么六爻卦是完备的</strong>：<strong>六爻＝阴阳各自完备的叠加＝宇宙最完整的表达单位。</strong></p><p><strong>与二十八、二十九、三十章的层次关系</strong>：</p><table tabindex="0"><thead><tr><th>章</th><th>内容</th></tr></thead><tbody><tr><td>第二十八章</td><td>数的结构（乾坤包六子）</td></tr><tr><td>第二十九章</td><td>数的天文对应（384 与闰年）</td></tr><tr><td>第三十章</td><td>数的内部推导（360＋24）</td></tr><tr><td><strong>第三十二章</strong></td><td><strong>数的哲学根源（为什么是三和六）</strong></td></tr></tbody></table><p><strong>从「是什么」→「从哪里来」→「为什么」——三个层次，逐层深入。</strong></p><h3 id="用-今天怎么进入这一章" tabindex="-1">用：今天怎么进入这一章 <a class="header-anchor" href="#用-今天怎么进入这一章" aria-label="Permalink to &quot;用：今天怎么进入这一章&quot;">​</a></h3><ul><li>记住三个阶段：<strong>起、偶、成</strong>；</li><li>记住「六＝完备」：<strong>不是一个数字，是一种「到此为止」的状态</strong>；</li><li>顺着钩子想（承接昇哥的问题）：<strong>「三是完备的」——完备的标准从哪来？</strong> 麻衣的理由是「两端＋中介」＝起、偶、成。<strong>这个逻辑其实是「三才」（天地人）的投影。</strong> 换一个文化体系（希腊四元素、印度五大），<strong>他们也可以说「四元素完备，无以加矣」。</strong> 我的看法：<strong>「完备」很可能是「描述系统的性质」，而不是「宇宙的性质」。</strong> 但这不构成对麻衣的驳倒——<strong>因为他从来没有声称「三是宇宙的绝对真理」，他说的是「三是完备的」</strong>（在他的体系里）。<strong>真正要小心的，是把「体系内的完备」当成「体系外的真理」。</strong> 而这正是麻衣自己反复警惕的：<strong>「不可得而容心」——一旦你以为自己抓住了宇宙的全部，你就已经离开了落处。</strong></li></ul><h2 id="【解读层】现代重述" tabindex="-1">【解读层】现代重述 <a class="header-anchor" href="#【解读层】现代重述" aria-label="Permalink to &quot;【解读层】现代重述&quot;">​</a></h2><p>数在三这里完成，将三重叠则得六；退行的方向也是六——这就是乾坤之数。</p><p>气的数，从一开始，在二处成偶，在三处完成，没有什么可以再加的了；将三重叠，就成为六。</p><p>然而三是少阳，六是太阳；三是春，六是夏。这是乾的数，是进数。</p><p>退行方向也是六：三是少阴，六是太阴；三是秋，六是冬。这是乾坤的数，是退数。</p><p>三爻为经卦、六爻为重卦，全都是因为这个道理。</p><h2 id="【解读层】我的理解" tabindex="-1">【解读层】我的理解 <a class="header-anchor" href="#【解读层】我的理解" aria-label="Permalink to &quot;【解读层】我的理解&quot;">​</a></h2><blockquote><p><strong>一句话</strong>：第三十二章回答的是一个「元问题」——<strong>为什么是六爻？因为气数到三就完了，三叠起来就是六。</strong></p></blockquote><p>可以按这几条慢慢写：</p><ul><li><strong>「起、偶、成」</strong>——这三个字是全章的骨。<strong>一起、二偶、三成</strong>：先有起点，再有对立，再有完成。<strong>「两端＋中介」就完备了——这是三的形而上理由。</strong></li><li><strong>「无以加矣」</strong>——「加」字用得好：<strong>不是「不够」，是「已经够到不能再加」。</strong> 三不是「小」，是「满」。</li><li><strong>「进数」与「退数」</strong>——两个六，方向相反，数值相同。<strong>麻衣的解释很关键：六不是「量」，是「完备状态」。</strong> 就像夏与冬：一个是最热，一个是最冷，<strong>两者都是「极」，所以都是六。</strong></li><li><strong>为什么六爻卦是完备的</strong>——因为<strong>六＝阴阳各自完备的叠加</strong>。<strong>六爻卦因此是「宇宙最完整的表达单位」</strong>——这句话解释了为什么偏偏是六。</li><li><strong>「凡以此而已」</strong>——麻衣收得很轻：<strong>这就是三画六画的全部理由。</strong> 没有神秘，只有「气数自然」。</li><li><strong>留给自己的问题</strong>（承接昇哥的钩子）：<strong>「三是完备的」——完备的标准从哪来？</strong> 我的看法：<strong>「完备」很可能是「描述系统的性质」，不是「宇宙的性质」。</strong> 「两端＋中介」这套逻辑，其实是三才（天地人）的投影；<strong>换一个文化，四元素、五大，也都可以说「无以加矣」。</strong> 但这不构成对麻衣的驳倒——<strong>因为他没声称「三是宇宙的绝对真理」，他说的是「三是完备的」（在他的体系里）。</strong> 真正要小心的是：<strong>把「体系内的完备」当成「体系外的真理」</strong>——<strong>而这正是麻衣自己反复警惕的：「不可得而容心」。</strong></li></ul><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li><a href="/Dao/yijing/zheng-yi-xin-fa/">正易心法总览</a></li><li><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-20">第二十章 · 唯乾与坤</a> — 「本之自然」（本章的同一立场）</li><li><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-28">第二十八章 · 乾坤六子</a> — 数的结构（本章追溯其根源）</li><li><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-33">第三十三章 · 进以此数</a> — 进退对称（本章的下一步）</li><li><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-34">第三十四章 · 五数十数</a> — 形的数（与本章「气的数」相对）</li></ul>`,24))])}}});export{m as __pageData,x as default};
